  if (!command) fail("Missing command");
  const db = await load();

  if (command === "add") {
    const options = optionValues(args, new Set(["--title", "--tags", "--due"]));
    const title = options.get("--title")?.trim();
    if (!title) fail("Title is required");
    const due = options.get("--due");
    if (due !== undefined && !isDate(due)) fail("Due date must be a valid YYYY-MM-DD date");
    const tags = [...new Set((options.get("--tags") || "").split(",").map((tag) => tag.trim().toLowerCase()).filter(Boolean))];
    const task: Task = { id: db.nextId++, title, tags, status: "open", createdAt: new Date().toISOString(), ...(due ? { due } : {}) };
    db.tasks.push(task);
    await save(db);
    console.log(JSON.stringify(task));
    return;
  }

  if (command === "list") {
    const options = optionValues(args, new Set(["--status", "--tag", "--overdue"]));
    const status = options.get("--status");
    const tag = options.get("--tag")?.trim().toLowerCase();
    const overdue = options.get("--overdue");
    if (status !== undefined && status !== "open" && status !== "done") fail("Status must be open or done");
    if (overdue !== undefined && !isDate(overdue)) fail("Overdue date must be a valid YYYY-MM-DD date");
    const tasks = db.tasks.filter((task) =>
      (!status || task.status === status) && (!tag || task.tags.includes(tag)) &&
      (!overdue || (task.status === "open" && task.due !== undefined && task.due < overdue)),
    ).sort((a, b) => a.id - b.id);
    console.log(JSON.stringify(tasks));
    return;
  }

  if (command === "done" || command === "delete") {
    if (args.length !== 1) fail(`${command} requires one ID`);
    const id = parseId(args[0]);
    const index = db.tasks.findIndex((task) => task.id === id);
    if (index === -1) fail(`Task ${id} not found`);
    if (command === "delete") {
      const [task] = db.tasks.splice(index, 1);
      await save(db);
      console.log(JSON.stringify(task));
      return;
    }
    const task = db.tasks[index];
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      await save(db);
    }
    console.log(JSON.stringify(task));
    return;
  }

  if (command === "stats") {
    if (args.length) fail("stats accepts no options");
    const today = todayLocal();
    const open = db.tasks.filter((task) => task.status === "open");
    console.log(JSON.stringify({ total: db.tasks.length, open: open.length, done: db.tasks.length - open.length, overdue: open.filter((task) => task.due && task.due < today).length }));
    return;
  }

  fail(`Unknown command: ${command}`);
}

